-- 212: 운영 패턴 사전 초기 데이터 — ops_patterns · ops_pattern_taste_signals · ops_pattern_common_rules 시드 (티켓 20261007_1633, 상위 20260930_1503 ③)
--
-- 이 파일은 생성 파일이다. 손으로 고치지 않는다. 원고를 고쳤으면 아래 명령으로 다시 만든다.
--   생성 명령: node scripts/ops-patterns-seed.mjs        (같은 원고인지 확인: node scripts/ops-patterns-seed.mjs --check)
--   원고: docs/service/content/OPS_PATTERNS.md
--   생성 때 개수: 패턴 18 · 샘플 63(주+보조) · 취향 신호 43(패턴별 40 + 공통 3) · 공통 규칙 7
--   칸 매핑 규칙은 scripts/ops-patterns-seed.mjs 머리 주석에 있다.
--
-- ⚠️ 이 파일은 **작성만 하고 실행하지 않았다.** 실행은 카리나가 사용자 승인 뒤에 한다.
--    Supabase는 staging·프로덕션 공용 단일 DB라 실행 즉시 프로덕션에 들어간다.
--
-- 동작:
--   - 세 INSERT는 모두 ON CONFLICT DO NOTHING이다. 다시 돌려도 사람이 S5에서 고친 행을 덮어쓰지 않는다.
--   - 넣는 순서는 패턴 → 취향 신호(패턴을 가리킨다) → 공통 규칙이다.
--   - COMMIT 앞의 확인 블록이 원고의 패턴 번호·취향 신호 쌍·공통 규칙 번호를 세어 어긋나면 트랜잭션을 되돌린다.
--   - 테이블은 210이 만든다. 210이 적용되지 않았으면 실행하지 않는다.

BEGIN;

-- ── ops_patterns ────────────────────────────────────────────────────────
INSERT INTO public.ops_patterns
  (pattern_no, name, principle, user_experience, menus, samples, card_shapes, knobs, pitfalls, status, pause_reason, origin)
VALUES
  -- P01 오늘 움직이면 열리는 자물쇠
  ('P01', '오늘 움직이면 열리는 자물쇠', '오늘 달리기나 체크인을 열쇠로 하는 자물쇠를 믹스의 한 칸이나 드랍 줍기 단계에 걸어 둔다. 재료는 다 모였는데 열쇠 한 칸만 비어 있으면, 그 열쇠를 얻으려고 오늘 몸을 움직일 이유가 생긴다. 열쇠 후보에 기본 액티비티 배지를 함께 넣어 걷는 유저와 초보 유저도 열 수 있게 한다.', '재료는 다 모았는데 오늘 한 번 달리거나 체크인하면 열리는 자물쇠가 남아 있어서, 오늘 나갈 이유가 하나 생긴다.', ARRAY['믹스', '체크인', '배지', '드랍']::text[], '[{"no":3,"name":"현장 도장 레시피","role":"main","impl":"지금 가능"},{"no":6,"name":"운동으로 열리는 레시피","role":"main","impl":"지금 가능"},{"no":7,"name":"땀 잠금 드랍","role":"main","impl":"O13(드랍 픽업에 당일 활동 거리·종류 조건을 거는 옵션)"},{"no":60,"name":"별 따러 가는 날","role":"related","impl":"지금 가능(미션판은 O2)"}]'::jsonb, '[{"shape":"list","note":"레시피 재료 타일과 비어 있는 열쇠 칸"},{"shape":"brief","note":"7의 드랍 소식"}]'::jsonb, '{"condition":{"open":"오늘 체크인 1회, 오늘 걷기·달리기 거리, 기본 액티비티 배지 보유를 열쇠로 열 수 있다.","closed":"상위 기록자만 통과하는 거리·페이스와, 열쇠 후보가 한 종류뿐이라 초보가 열 수 없는 조건이다."},"place":{"open":"산·역·공원·관광명소·경기장처럼 지점 카테고리에서 체크인 배지를 골라 열쇠로 걸 수 있다.","closed":"공통 규칙뿐이다."},"time":{"open":"열쇠는 오늘 얻는 배지(믹스)나 당일 활동(드랍)이다.","closed":"심야(22:00~05:00) 시간대 활동을 열쇠로 미리 권하는 조건이다."},"reward":{"open":"자물쇠가 열린 뒤 얻는 믹스 결과 배지나 줍는 아이템이다. 결과 등급은 고른 결과 배지의 등급이다.","closed":"열쇠를 못 채운 유저에게서 재료나 기회를 빼앗는 방식이다."},"tribe":{"rule":"캐논 10종 전체에서 열쇠 행동(운동 종류)과 장소의 성격에 맞춰 TRIBES.md 매핑표(소재·시간대·POI 유형)로 고른다.","example":"아날로그 수집가 — 길에서 열쇠를 주워 부적 삼는 이들이라 「오늘의 열쇠」로 여는 자물쇠가 어울린다."}}'::jsonb, '6·7의 사용자 의견은 열쇠 후보에 기본 액티비티 배지 수준을 함께 넣어 걷는 유저와 초보 유저도 열 수 있게 하는 것이고, 7의 자물쇠는 줍는(픽업) 단계에 건다. 3처럼 특정 산 정상 체크인을 열쇠로 걸면 그 지역 밖 유저가 못 열므로 다른 지점·액티비티 배지 후보를 함께 둔다.', 'active', NULL, 'seed'),
  -- P02 하루 중 짧은 시간에만 열린다
  ('P02', '하루 중 짧은 시간에만 열린다', '일몰 전후 15분이나 점심 12~15시처럼 하루 중 짧은 시간에만 열리는 배지·미션을 두면, 그 시간에 맞춰 나가게 된다. 시간대는 하늘이 바뀌는 때나 생활 리듬에 맞는 때로 잡고, 놓쳐도 손해가 없게 한다.', '점심 세 시간이나 일몰 전후처럼 짧게 열리는 것이 있어서, 그 시간에 맞춰 나갈지 정해 볼 수 있다.', ARRAY['배지', '미션']::text[], '[{"no":8,"name":"매직 아워 15분 유실물","role":"main","impl":"지금 가능(계절별 고정 시간대로 근사)"},{"no":9,"name":"새벽 한 바퀴·노이즈 캔슬링 0","role":"main","impl":"O1(미션 조건에 시간대·요일·기온 키를 넘기는 옵션)"},{"no":57,"name":"세 시간 게릴라","role":"main","impl":"O1"},{"no":30,"name":"무명 트럭 목격 제보","role":"related","impl":"지금 가능"}]'::jsonb, '[{"shape":"square","note":"미션"},{"shape":"brief","note":"배지 1개 소개"}]'::jsonb, '{"condition":{"open":"시간대 안에서 활동 1회나 체크인 1회를 조건으로 열 수 있다.","closed":"시간대 안의 페이스·기록 경쟁이다."},"place":{"open":"일몰·이른 아침은 관광명소·자전거길/트레일·공원처럼 평탄하고 사람이 오가는 곳, 점심은 음식점·편의점·역으로 열 수 있다.","closed":"산, 그리고 해가 진 뒤·해 뜨기 전 외진 곳으로 보내는 조건이다."},"time":{"open":"일몰 전후 15분(8), 점심 12~15시(57), 새벽·이른 아침 05:00~08:00(9)을 열 수 있다.","closed":"심야 시간대 활동을 미리 권하는 조건과 초 단위 카운트다운이다."},"reward":{"open":"새 배지나 포인트다.","closed":"시간대를 놓친 유저에게 주는 불이익이다."},"tribe":{"rule":"캐논 10종 전체에서 TRIBES.md 「시간대 화자 원칙」 표의 시간대 행을 따라 고른다.","example":"셔터 마피아 — 새벽·황혼(매직 아워)의 시간대 주 화자다."}}'::jsonb, '9의 사용자 의견은 비슷한 액티비티 배지가 이미 있으므로 운영용으로는 미션으로 열고 새 배지나 포인트를 주는 것이며, 심야 조건은 미션으로 열지 않는다(06 3.1 윤리 원칙). 새벽 카드는 최근 새벽 시간대 활동 기록이 있는 유저에게만 보인다(공통 규칙 4). 57은 기상특보(폭염 포함) 발효일에 시간대 미션·카드를 열지 않고, 폭염 기간의 57은 실내 지점(음식점·편의점·역) 체크인 조건으로만 연다. 8은 계절별 고정 시간대로 근사하므로 실제 일몰 시각이라고 말하지 않는다.', 'active', NULL, 'seed'),
  -- P03 달력의 그날에만 열린다
  ('P03', '달력의 그날에만 열린다', '요일·절기·공휴일·경기일처럼 달력에 표시된 날에만 열리는 미션·드랍·컬렉션 보상을 두면, 그날을 기다리고 챙기게 된다. 날짜를 미리 알 수 있으므로 놀라게 하지 않고, 요일은 매주 돌아온다.', '오늘이 절기이거나 경기장에서 달리는 날이라서 오늘 하루만 받을 수 있는 것이 있다는 걸 카드로 알고 챙긴다.', ARRAY['홈피드', '미션', '컬렉션', '드랍']::text[], '[{"no":11,"name":"오늘의 룰","role":"main","impl":"O1·O3(배수 보너스는 경제 수치 변경이라 미션·배지 보상으로 대신한다)"},{"no":16,"name":"절기 수첩","role":"main","impl":"지금 가능(미션 보상. 인벤토리가 가득 차면 지급을 건너뛴다, 06 7절)"},{"no":62,"name":"직관의 날","role":"main","impl":"O2(체크인 미션에 지점 카테고리 조건을 더하는 옵션)"},{"no":71,"name":"특일 게릴라","role":"main","impl":"O3(특일·날씨 태그를 미션 노출·드랍 조건으로 쓰는 옵션)"},{"no":44,"name":"기념일 배지·카드","role":"related","impl":"O5(JAM! 배지에 가입 경과일 지표를 더하는 옵션)"}]'::jsonb, '[{"shape":"square","note":"미션"},{"shape":"brief","note":"드랍"},{"shape":"poster","note":"절기 컬렉션 소식, 대표 이미지가 있을 때"}]'::jsonb, '{"condition":{"open":"그날 활동 1회(16), 새 지점 첫 방문 같은 요일 규칙(11), 경기장 체크인(62)을 열 수 있다.","closed":"배수 보너스, 날짜를 놓치면 손해를 보는 조건, 날씨 태그(비·폭우·폭염·한파)를 미션·드랍의 열림 조건으로 거는 것이다. 특일 태그만 쓴다."},"place":{"open":"62는 경기장, 나머지는 지점 카테고리 전체에서 열 수 있다. 경기장은 지점이 적어 지역이 쏠리므로 지역을 돌아가며 쓴다. 경기일은 경기장 지점을 쓰는 운영일로 정하고 실존 리그·구단 일정에 맞추지 않는다.","closed":"공통 규칙뿐이다."},"time":{"open":"요일, 24절기 당일, 공휴일·기념일 태그, 경기일을 열 수 있다. 공휴일 태그 중 현충일은 열지 않는다.","closed":"종교 의례일을 의례로 다루는 것(성탄절·부처님오신날은 \"쉬는 날\"로만), 국가 추념일·참사 추모일, 상표명이 붙은 기념일·챌린지다(금기 3·5·6)."},"reward":{"open":"절기 컬렉션의 아이템배지(16)와 미션·배지 보상을 열 수 있다. 16의 절기 컬렉션은 신설 컬렉션이라 컬렉션 런칭 세션을 거친다(06 3.2).","closed":"공통 규칙뿐이다."},"tribe":{"rule":"캐논 10종 전체에서 TRIBES.md 표 1의 「24절기」「전통 기념일·공휴일」「지역 축제·행사」 같은 범주 행이 정한 우선순으로 고른다. 16의 소속 트라이브는 표 1의 24절기 행에서 고른다.","example":"숲속의 갱단 — 24절기 행의 화자라 절기 수첩(16)을 절기마다 달라지는 산자락·공원 이야기로 말하기 좋다."}}'::jsonb, '11의 사용자 의견은 배수 보너스가 경제 수치 변경이므로 미션·배지 보상으로 대신하고, 날씨가 나쁜 날의 규칙은 밖으로 나가게 하지 않고 실내 놀거리로 채우는 것이다(P04와 같은 방향). 16은 절기 당일에만 열리는 활동 1회 미션에 아이템배지를 보상으로 거는 제안이다. 62는 관람이 아니라 경기장 트랙에서 달리는 날로 쓴다.', 'active', NULL, 'seed'),
  -- P04 궂은 날엔 집에서 할 것을 준다
  ('P04', '궂은 날엔 집에서 할 것을 준다', '비가 오거나 기상특보가 내려 나가기 어려운 날에는 홈피드를 인벤토리 정리·믹스·서사 읽기 같은 실내 놀거리로 채운다. 나가라고 하지 않고 앱을 열 이유만 주므로, 못 나가는 날에도 흐름이 끊기지 않는다.', '비 오는 날 홈피드를 열면 나가라는 말 대신 집에서 해 볼 것이 놓여 있다.', ARRAY['홈피드']::text[], '[{"no":14,"name":"비 오는 날의 채비","role":"main","impl":"지금 가능"},{"no":15,"name":"정비소의 날","role":"main","impl":"지금 가능"},{"no":11,"name":"오늘의 룰","role":"related","impl":"O1·O3(배수 보너스는 경제 수치 변경이라 미션·배지 보상으로 대신한다)"}]'::jsonb, '[{"shape":"brief","note":""},{"shape":"hero","note":"서사 읽기를 권할 때는 `hero`(기사)"}]'::jsonb, '{"condition":{"open":"날씨 노출 태그가 뜬 날, 카드가 여는 행동은 인벤토리 정리·믹스·서사 읽기다.","closed":"나가서 활동해야 받는 조건이다."},"place":{"open":"정하지 않는다(집에서 하는 것).","closed":"야외 지점 체크인을 조건으로 거는 것이다."},"time":{"open":"태그가 뜬 그날 하루다.","closed":"공통 규칙뿐이다."},"reward":{"open":"새 보상을 만들지 않고 기존 믹스·서사·인벤토리 활동의 결과를 쓴다.","closed":"궂은 날 야외 활동에 주는 보너스다."},"tribe":{"rule":"캐논 10종 전체에서 TRIBES.md 표 1의 「비」「폭우·태풍」 행을 따라 고르고, 특보일 안전 안내는 공통 화자가 쓴다.","example":"장비병 환자들 — 폭우·태풍 날 실내 정비의 화자이고, 「정비소의 날」(15)과 같은 결이며 외출 권유가 없다."}}'::jsonb, '악천후(기상특보 포함) 조건은 미리 권하는 미션으로 열지 않고, 지난 뒤 알려 주는 회고형 배지로만 준다(06 3.1, TRIBES.md 금기 9). 14는 06에 원문 설명이 없어 이름으로 재구성했고, 「채비」가 나갈 준비로 읽히지 않게 인벤토리·장비 정리 뜻으로만 쓴다. 특보가 내린 날을 가리는 노출 태그가 있는지는 기획 때 홈피드 태그 표에서 확인한다.', 'active', NULL, 'seed'),
  -- P05 찾는 것에 이름표를 단다
  ('P05', '찾는 것에 이름표를 단다', '찾을 아이템이나 컬렉션 한 칸에 「이번 주의 한 칸」「수배 전단」처럼 이름을 붙여 부르고 그것을 지도에 뿌리면, 유저가 그 하나를 찾으려고 줍게 된다. 레시피의 첫 재료인 쪽지를 뿌려 그 레시피를 시작하게 하는 것도 같은 방식이다.', '이번 주에 찾을 것이 하나로 정해져 있어서, 어디서 주울지 한 가지만 신경 쓰면 된다.', ARRAY['홈피드', '드랍', '믹스']::text[], '[{"no":1,"name":"레시피 쪽지","role":"main","impl":"지금 가능(쪽지만 담은 컬렉션을 드랍 대상으로 지정. 쪽지 아이템만 골라 뿌리려면 O6)"},{"no":19,"name":"이번 주의 한 칸","role":"main","impl":"지금 가능"},{"no":64,"name":"수배 전단","role":"main","impl":"O6(즉시 배포에 대상 지점·날짜 예약·아이템 지정을 더하는 옵션)"},{"no":65,"name":"보물 지도 드랍","role":"related","impl":"O6"}]'::jsonb, '[{"shape":"poster","note":"수배 전단처럼 이미지가 주인공일 때"},{"shape":"brief","note":"드랍 소식"}]'::jsonb, '{"condition":{"open":"컬렉션 한 칸, 아이템 1종, 레시피 첫 재료 쪽지(아이템배지이고 믹스에 넣으면 소각된다)를 찾는 대상으로 열 수 있다.","closed":"못 찾은 유저에 대한 불이익, 그리고 epic·mystic 아이템과 미스터리 헌터 소속 아이템을 이번 주의 한 칸·수배 전단의 대상으로 거는 것이다."},"place":{"open":"정기 배포의 카테고리 선택, 그리고 날짜 예약(O6)의 지점 종류+총 개수와 지점 직접 지정 안에서 열 수 있다. 시각은 KST 정시로 정한다.","closed":"한 카테고리나 한 지역에 몰아 뿌려 전국 유저 일부가 못 줍는 구성, 그리고 한 지점에 겹쳐 쌓는 구성이다(지점 직접 지정은 겹침 한도가 없고, 놓은 드랍은 내리지 않는다)."},"time":{"open":"한 주 단위다.","closed":"공통 규칙뿐이다."},"reward":{"open":"찾은 아이템 자체와 컬렉션 진행이다.","closed":"공통 규칙뿐이다."},"tribe":{"rule":"캐논 10종 전체에서 찾는 대상의 소재는 TRIBES.md 표 1, 뿌리는 지점의 종류는 표 2(POI 유형)로 고른다.","example":"낭만 미식가 — 털린 간식을 「찾습니다」로 붙이는 피해자 쪽이라 수배 전단이 분실 전단으로 읽힌다."}}'::jsonb, '19·64는 06에 원문 설명이 없어 이름으로 재구성했으므로 기획 때 다시 확인한다. 수배 전단은 사람·유저·트라이브가 아니라 아이템을 찾는 전단으로만 쓴다. 발행 주체는 세계관 안의 곳(분실물 센터 999 등)이나 물건을 털린 쪽이고, 현상금·검거·범인·체포 어휘를 쓰지 않으며, 제목은 「○○를 찾습니다」 계열로 쓴다. 쪽지를 한 번만 뿌리면 늦게 온 유저가 레시피를 시작할 수 없으므로 반복해서 뿌린다(제안).', 'active', NULL, 'seed'),
  -- P06 이번 주 뿌리는 쪽을 바꾼다
  ('P06', '이번 주 뿌리는 쪽을 바꾼다', '이번 주 앰비언트 드랍에서 뿌리는 컬렉션이나 트라이브의 것을 바꾸면, 새로 눈에 띄는 것부터 주워 보게 된다. 바꾸는 것은 「무엇을 뿌리는가」뿐이고 확률과 등급 비율은 그대로 둔다.', '이번 주 지도에 지난주와 다른 것이 많이 보여서, 새 것부터 주워 본다.', ARRAY['드랍(앰비언트)']::text[], '[{"no":32,"name":"트라이브 바람","role":"main","impl":"지금 가능(경제 검토)"},{"no":43,"name":"등급 물결 주간","role":"main","impl":"지금 가능(경제 검토)"},{"no":19,"name":"이번 주의 한 칸","role":"related","impl":"지금 가능"}]'::jsonb, '[]'::jsonb, '{"condition":{"open":"앰비언트 드랍이 뿌릴 컬렉션·트라이브를 지정하는 것만 연다. 뿌리는 비중을 올리는 손잡이는 열지 않는다.","closed":"드랍 엔진 수치 조정이다."},"place":{"open":"정기 배포의 카테고리 선택 안에서 열 수 있다.","closed":"특정 지점 지정이다. 날짜 예약(O6)으로 지점을 고를 수 있지만, 놓을 곳을 고르는 일은 P05·P07이 맡고 이 패턴은 무엇을 뿌리는가만 바꾼다."},"time":{"open":"한 주 단위로 바꾼다.","closed":"주 중에 즉석으로 바꾸는 서버 생성과 생성 주기 단축이다(06 3.1)."},"reward":{"open":"새 보상을 만들지 않고 뿌린 것을 줍는 것이 보상이다.","closed":"공통 규칙뿐이다."},"tribe":{"rule":"캐논 10종 전체에서 최근 4주에 덜 뿌린 쪽부터 지정한다. 미스터리 헌터의 것은 드랍 시점을 인접 그래프와 드랍 엔진이 정하므로 지정 대상에서 뺀다.","example":"포션 연금술사 — 가을 행의 화자이고, 이번 주 바람을 합성 재료 이야기로 말하되 섭취량·효능 문장은 쓰지 않는다."}}'::jsonb, '32·43은 경제 검토를 거쳐야 하는 샘플이라 혜린의 리스크 점검으로 넘긴다. 43의 사용자 의견은 경제 검토 뒤 조정 수단의 하나로 쓰는 것인데, 이 패턴은 등급 비율 손잡이를 열지 않고 어느 컬렉션을 뿌릴지만 다룬다. 43은 카드·미션 이름에 「등급 물결」을 쓰지 않는다(희귀 등급이 늘어난다는 약속으로 읽힌다). 32는 06에 원문 설명이 없어 이름으로 재구성했다. 특정 컬렉션만 뿌려 다른 컬렉션 완성을 늦추는지는 규칙으로 막지 않고 어드민 데이터를 보고 운영자가 판단한다(06 3.1).', 'active', NULL, 'seed'),
  -- P07 놓인 곳을 알려 준다
  ('P07', '놓인 곳을 알려 준다', '그날 드랍이 놓인 곳을 종류(오늘은 산), 지점 3곳 예보, 기사 속 힌트, 목격담 중 알맞은 정도로 알리면, 유저가 그곳을 찾아 나선다. 자세히 알릴수록 보물찾기에 가깝고 얕게 알릴수록 산책의 이유에 가깝다.', '오늘 어디에 무엇이 놓였는지 카드가 알려 줘서, 나가는 곳을 정하기 쉽다.', ARRAY['홈피드', '드랍', '동기화 화면(46)']::text[], '[{"no":12,"name":"오늘의 재료 지도","role":"main","impl":"지금 가능"},{"no":13,"name":"반짝 지점 예보","role":"main","impl":"O6(즉시 배포에 대상 지점·날짜 예약·아이템 지정을 더하는 옵션)"},{"no":28,"name":"도시 괴담 목격담","role":"main","impl":"지금 가능(등급 확장 전제)"},{"no":65,"name":"보물 지도 드랍","role":"main","impl":"O6"},{"no":46,"name":"캐러셀 끝 카드","role":"aux","impl":"O10(동기화 캐러셀 끝 카드 종류를 고르는 옵션)"},{"no":24,"name":"나눔 지점","role":"related","impl":"지금 가능"},{"no":63,"name":"조용한 지점 순찰","role":"related","impl":"O12(지점별 이번 주 방문 수 표시 옵션)"},{"no":64,"name":"수배 전단","role":"related","impl":"O6(즉시 배포에 대상 지점·날짜 예약·아이템 지정을 더하는 옵션)"}]'::jsonb, '[{"shape":"brief","note":"드랍·예보"},{"shape":"hero","note":"힌트나 목격담을 기사로 쓸 때는 `hero`"}]'::jsonb, '{"condition":{"open":"알리는 정도는 장소 종류, 지점 3곳 예보, 힌트 중에서 고른다. 목격담은 28 전용이며 epic·mystic이 실제로 드랍되거나 픽업된 뒤의 소식에만 쓴다.","closed":"뽑기처럼 보이는 추첨 방식이다."},"place":{"open":"정기 배포의 카테고리 선택, 그리고 날짜 예약(O6)의 지점 종류+총 개수와 지점 직접 지정 안에서 열 수 있다. 13은 전국에 유저가 있으므로 지역을 돌아가며 운영한다. 65는 날짜 예약이나 지정 배포(O6의 「지금」)로 몇몇 지점에 희귀 등급 아이템을 직접 골라 놓고 기사에는 힌트만 준다.","closed":"한 지역에만 몰아 알리는 것, 그리고 한 지점에 겹쳐 쌓는 구성이다(지점 직접 지정은 겹침 한도가 없고, 놓은 드랍은 내리지 않는다)."},"time":{"open":"그날 하루의 드랍이다.","closed":"공통 규칙뿐이다."},"reward":{"open":"그날 뿌린 아이템이다. 희귀 등급 배포도 기존 드랍 엔진 범위 안이다.","closed":"공통 규칙뿐이다."},"tribe":{"rule":"캐논 10종 전체에서 12·13·65는 뿌린 지점의 종류를 TRIBES.md 표 2(POI 유형)로 고른다.","example":"숲속의 갱단 — 산·공원에 보물을 슬쩍 흘려두는 쪽이라 놓인 곳 귀띔에 어울린다(28 목격담은 미스터리 헌터 노출 원칙을 따른다)."}}'::jsonb, '13의 사용자 의견은 뽑기가 아니라 예보 방식으로 하고, 전국에 유저가 있으므로 지역을 돌아가며 운영하는 것이다. 46의 사용자 의견은 끝 카드의 종류를 상황에 따라 바꾸는 것이다. 켜 두면 계속 보이는 장치라 매주 기획 대상이 아니다. 28은 (1) 3인칭 목격담·소문 형식으로 쓰고, (2) 주운 유저·정확한 시각·정확한 지점을 쓰지 않고, (3) 미스터리 헌터가 유저에게 말을 걸거나 함께 가자는 어휘를 쓰지 않고, (4) 러너스 하이를 목표로 걸지 않고, (5) 일간 노출 상한은 운영이 정한 값을 따르되 값이 정해지기 전에는 쓰지 않는다. 65가 epic·mystic이면 기사도 28과 같은 노출 원칙을 따른다.', 'active', NULL, 'seed'),
  -- P08 같은 종류의 곳을 채운다
  ('P08', '같은 종류의 곳을 채운다', '역·노선·산처럼 같은 종류의 곳을 다녀간 수가 도장판으로 보이면, 안 가 본 다음 곳을 찾아가게 된다. 유저가 이미 하는 체크인이 그대로 진행도가 된다.', '역이나 산에 다녀간 수가 도장처럼 쌓이고, 다음 도장이 어느 곳인지 궁금해진다.', ARRAY['JAM! 배지']::text[], '[{"no":17,"name":"분실물 센터 999 창구","role":"main","impl":"지금 가능(역 카테고리 체크인 배지 수 지표)"},{"no":59,"name":"노선 도장","role":"main","impl":"지금 가능(미션판은 O2)"},{"no":72,"name":"카테고리 수집가","role":"main","impl":"지금 가능"},{"no":3,"name":"현장 도장 레시피","role":"related","impl":"지금 가능"},{"no":41,"name":"단골 명패","role":"related","impl":"O5"}]'::jsonb, '[{"shape":"brief","note":"배지 1개"},{"shape":"list","note":"단계 배지 여러 개"}]'::jsonb, '{"condition":{"open":"카테고리별 체크인 배지 수, 지정한 체크인 배지 목록 중 보유 수(노선 도장)에 단계를 걸 수 있다.","closed":"짧은 기간 안에 몰아 다녀야 하는 속도 조건과 기한 안에 못 채우면 사라지는 진행도다."},"place":{"open":"역, 산, 편의점, 음식점, 공원, 미슐랭, 관광명소, 경기장 카테고리를 쓸 수 있고 노선은 역 카테고리 안의 묶음이다. 미슐랭 카테고리는 서울 지점 전용이므로, 개수 배지는 서울 한정 문안으로 두거나 역·산·공원 같은 전국 카테고리와 나란히 둔다.","closed":"한 카테고리로만 몰아 다른 지역 유저가 못 채우는 구성이다."},"time":{"open":"상시로 두는 장기 배지다.","closed":"기간이 끝나면 회수되는 진행도다."},"reward":{"open":"JAM! 배지다. 행동 횟수형은 포인트를 작게, 달성형은 크게 주되 기존 범위 안이다.","closed":"공통 규칙뿐이다."},"tribe":{"rule":"캐논 10종 전체에서 카테고리에 맞는 트라이브를 TRIBES.md 표 2(POI 유형)로 고른다.","example":"비트 마에스트로 — 기차·지하철·경기장 행이라 역 한 곳마다 한 박자씩 도장이 채워지는 그림이다."}}'::jsonb, '표기는 앱 카테고리 라벨과 같은 「미슐랭」으로 통일한다. 유저에게 나가는 문안(미션·카드 제목, 배지 이름, 본문)에는 브랜드 글자와 별·스타·등급 어휘를 쓰지 않고 「미식 지점」 같은 세계관 말로 부른다. 체크인 배지 수 기준이라 같은 지점을 반복해도 늘지 않는 점을 기획 때 확인한다.', 'active', NULL, 'seed'),
  -- P09 운동하는 김에 도장을 찍는다
  ('P09', '운동하는 김에 도장을 찍는다', '운동 조건과 들를 곳을 한 코스로 묶으면, 운동하는 길이 도장 있는 곳을 지나도록 바뀌게 된다. 산 세 곳 체크인과 누적 고도를 하나의 미션으로 묶는 식이다.', '달리거나 걷는 길에 도장 찍을 곳을 하나 끼워 넣으면, 그날 운동이 하나의 코스가 된다.', ARRAY['미션', 'JAM! 배지']::text[], '[{"no":18,"name":"산 도장 코스","role":"main","impl":"O2(체크인 미션에 지점 카테고리·지점 묶음 조건을 더하는 옵션)"},{"no":60,"name":"별 따러 가는 날","role":"main","impl":"지금 가능(미션판은 O2)"},{"no":61,"name":"보급소 스탬프","role":"main","impl":"지금 가능(미션판은 O2)"},{"no":3,"name":"현장 도장 레시피","role":"related","impl":"지금 가능"},{"no":6,"name":"운동으로 열리는 레시피","role":"related","impl":"지금 가능"}]'::jsonb, '[{"shape":"square","note":"미션"},{"shape":"brief","note":"배지 1개"},{"shape":"list","note":"배지 여러 개"}]'::jsonb, '{"condition":{"open":"체크인 N곳과 누적 고도(18), 운동한 날의 지점 체크인(60), 활동 중 편의점 체크인(61)을 한 코스로 묶을 수 있다.","closed":"속도·거리 상위권 조건이다."},"place":{"open":"산(18), 미슐랭(60, 서울 지점 전용), 편의점(61)이고 공원·관광명소·역으로도 넓힐 수 있다.","closed":"해가 진 뒤와 해 뜨기 전의 산 코스다."},"time":{"open":"코스 단위의 상시나 기간형 미션이고, 60은 운동한 그날이 기준이다.","closed":"공통 규칙뿐이다."},"reward":{"open":"코스를 완주하는 달성형 배지와 미션 보상이다.","closed":"공통 규칙뿐이다."},"tribe":{"rule":"캐논 10종 전체에서 코스가 지나는 지점의 종류를 TRIBES.md 표 2(POI 유형)로 고른다.","example":"아스팔트 레인저 — 산 행이라 산 도장 코스(18)의 화자다(「생존의 증표」류 문구는 쓰지 않는다)."}}'::jsonb, '60의 카드·미션 문안은 별·스타·등급·순위 어휘를 쓰지 않고 무명(無名)을 쫓는 미식 서사로 쓴다. 「별 따러 가는 날」은 06의 샘플 이름일 뿐이고 유저에게 나가는 제목은 새로 짓는다. 미슐랭 표기와 문안 원칙은 P08과 같은 판단을 따른다. 운동 뒤 식사 이야기에 칼로리·소모량·체중 어휘를 쓰지 않고, 술을 권하지 않는다(TRIBES.md 금기 2·10). 61은 보충제·섭취를 권하지 않는다. 60·61의 미션판은 O2가 있어야 한다.', 'active', NULL, 'seed'),
  -- P10 이야기를 회차로 나눠 푼다
  ('P10', '이야기를 회차로 나눠 푼다', '이야기를 월·수·금처럼 회차로 나눠 열면, 다음 회를 보려고 정해진 날에 다시 열어 보게 된다. 각 회는 홈피드 기사·드랍·미션·믹스 중 하나로 열리고, 놓친 유저도 이어서 볼 길을 남겨 둔다.', '월요일에 1막을 보고 수요일에 2막이 열리는 것을 기다려서, 정해진 날에 다시 앱을 열어 본다.', ARRAY['홈피드', '드랍', '믹스', '배지', '미션']::text[], '[{"no":2,"name":"레시피 3부작 연재","role":"main","impl":"지금 가능"},{"no":30,"name":"무명 트럭 목격 제보","role":"main","impl":"지금 가능"},{"no":31,"name":"털린 핫도그 추적전","role":"main","impl":"지금 가능"},{"no":38,"name":"챕터 연재 + 결말 아이템","role":"related","impl":"지금 가능"}]'::jsonb, '[{"shape":"hero","note":"기사·연재"},{"shape":"square","note":"이어지는 자원의 모양(미션 `square`, 레시피 `list`)"},{"shape":"list","note":"이어지는 자원의 모양(미션 `square`, 레시피 `list`)"}]'::jsonb, '{"condition":{"open":"회마다 재료 찾기, 단서 배지, 미션 완료, 믹스 중 하나를 걸 수 있고, 믹스에 실패해도 에필로그(홈피드 기사)를 볼 수 있다.","closed":"앞 회를 놓치면 뒤 회를 볼 수 없는 조건과 회차를 따라잡으라는 압박이다."},"place":{"open":"회마다 지점 카테고리를 돌려 쓸 수 있다.","closed":"공통 규칙뿐이다."},"time":{"open":"월·수·금 3회(2)나 주차별 3~4주 연재를 열 수 있다. 30은 야식 시간대 활동을 지나고 나서 단서 배지로 알려 준다.","closed":"야식 시간대 활동을 미리 권하는 조건이다."},"reward":{"open":"단서 배지, 결말 배지, 믹스 결과 배지, 에필로그 기사다.","closed":"앞 회의 보상을 뒤 회 참여의 전제로 걸어 놓칠까 봐 불안하게 만드는 것이다."},"tribe":{"rule":"캐논 10종 전체에서 이야기의 화자를 고른다. 미스터리 헌터는 연재의 화자·주인공으로 쓰지 않고, 등장은 노출 원칙의 세 경우(epic·mystic 실제 드랍 소식, 등록 조합 레시피 소개, 사람이 직접 고른 경우)에 한하며 소문 형식이다. 짝은 인접 표에 명시된 쌍에서 고르고, 두 특수 노드(작심삼일 클럽의 전 트라이브 약한 가중치, 미스터리 헌터의 전역)는 짝의 근거로 쓰지 않는다.","example":"낭만 미식가 — 환상의 푸드트럭 「무명」을 쫓는 30 연재의 주인공이고, 31 교차 연재의 짝은 인접한 숲속의 갱단이다."}}'::jsonb, '30의 사용자 의견은 야식 시간대 활동을 미리 권하지 않고, 지나고 나서 단서 배지로 알려 주는 것이다(06 3.1 윤리 원칙). 31은 06에 원문 설명이 없어 이름으로 재구성했다. 회차 카드도 날짜당 3~5장 안에 들어가야 한다. 세계관·코퍼스 원문 인용은 공통 규칙 5를 따른다.', 'active', NULL, 'seed'),
  -- P11 얻은 것이 다음 문을 연다
  ('P11', '얻은 것이 다음 문을 연다', '앞 단계에서 받은 배지나 아이템을 다음 관문의 열쇠로 삼으면, 한 번으로 끝내지 않고 이어서 하게 된다. 미션 A의 완료 배지가 미션 B를 열거나, 특정 배지를 가진 유저에게만 숨은 미션이 보이는 식이다.', '지난번에 받은 배지가 다음 미션이나 믹스를 여는 열쇠로 쓰여서, 이어서 해 볼 이유가 생긴다.', ARRAY['미션', '믹스']::text[], '[{"no":38,"name":"챕터 연재 + 결말 아이템","role":"main","impl":"지금 가능"},{"no":49,"name":"배지가 여는 숨은 미션","role":"main","impl":"지금 가능"},{"no":53,"name":"사슬 미션","role":"main","impl":"지금 가능"},{"no":1,"name":"레시피 쪽지","role":"related","impl":"지금 가능(쪽지만 담은 컬렉션을 드랍 대상으로 지정. 쪽지 아이템만 골라 뿌리려면 O6)"},{"no":34,"name":"아깝다 부스러기","role":"related","impl":"O5(JAM! 배지에 행동 지표를 더하는 옵션)"},{"no":47,"name":"믹스 결과 등급","role":"related","impl":"지금 가능"}]'::jsonb, '[{"shape":"square","note":"미션"},{"shape":"list","note":"결말 아이템·재료 타일이 있는 레시피"}]'::jsonb, '{"condition":{"open":"앞 배지 보유(배지 보유자 전용 노출), 결말 아이템(다음 챕터 믹스의 열쇠), 숨김·예약 노출을 열 수 있다.","closed":"앞 단계를 놓친 유저가 뒤 단계에서 영영 배제되는 구성이다."},"place":{"open":"단계마다 지점 카테고리를 바꿔 이을 수 있다.","closed":"같은 카테고리로만 이어 쏠리는 사슬이다."},"time":{"open":"3~4주로 이어지는 사슬(53), 주차별 챕터(38)를 열 수 있다.","closed":"공통 규칙뿐이다."},"reward":{"open":"다음 문을 여는 완료 배지, 결말 아이템, 미션 보상 배지다.","closed":"사슬을 끝까지 마쳐야 앞 단계 보상을 주는 후불 방식이다."},"tribe":{"rule":"캐논 10종 전체에서 미션의 트라이브 연결을 필수로 두고, 단계마다 화자를 바꿀 때 짝은 인접 표에 명시된 쌍에서 고른다. 두 특수 노드(작심삼일 클럽의 전 트라이브 약한 가중치, 미스터리 헌터의 전역)는 짝의 근거로 쓰지 않는다.","example":"아스팔트 레인저 — 훈련장의 관문 통과형이라 「앞 관문의 증표가 다음 관문을 연다」가 자연스럽다(관문에 악천후를 걸지 않는다)."}}'::jsonb, '미션은 기간형이고 배지는 영구라서, 앞 미션이 끝나면 열쇠 배지를 얻을 길이 닫힌다. 늦게 온 유저를 위해 열쇠를 얻을 다른 길이나 사슬의 재개설을 함께 정한다(제안). 49는 배지가 없는 유저에게 미션이 보이지 않으므로 「놓쳤다」는 문구를 쓰지 않는다. 38은 회차를 날짜로 나누면 P10, 얻은 것으로 이으면 P11로 가른다.', 'active', NULL, 'seed'),
  -- P12 믹스가 해 볼 만해진다
  ('P12', '믹스가 해 볼 만해진다', '믹스가 실패해도 부스러기·배지 같은 흔적이 남고 성공은 결과 등급과 최초 성공 배지로 특별해지면, 부담 없이 재료를 합쳐 보게 된다. 성공 확률은 건드리지 않고, 실패와 성공을 대하는 방식만 바꾼다.', '믹스가 실패해도 무언가 남고, 성공하면 재료보다 높은 등급이 나와서 한번 해 볼 만하다.', ARRAY['믹스', 'JAM! 배지', '미션', '인벤토리(42)']::text[], '[{"no":34,"name":"아깝다 부스러기","role":"main","impl":"O5(JAM! 배지에 행동 지표를 더하는 옵션)"},{"no":39,"name":"레시피 최초 성공 배지","role":"main","impl":"O5"},{"no":47,"name":"믹스 결과 등급","role":"main","impl":"지금 가능"},{"no":79,"name":"연금술 견습·장인","role":"main","impl":"O5"},{"no":42,"name":"최초 발급자 칩","role":"aux","impl":"O9(인벤토리·컬렉션에 표시 칩을 더하는 옵션)"},{"no":2,"name":"레시피 3부작 연재","role":"related","impl":"지금 가능"}]'::jsonb, '[{"shape":"list","note":"레시피 재료 타일, 배지 여러 개"},{"shape":"brief","note":"배지 1개"}]'::jsonb, '{"condition":{"open":"믹스 시도 횟수(실패 포함), 성공 횟수, 레시피 최초 성공, 믹스 결과물을 요구하는 미션을 열 수 있다.","closed":"연속 실패 뒤 성공 확률 보정, 실패 횟수를 늘리도록 부추기는 조건, 「아깝게 놓쳤다」 연출이다."},"place":{"open":"믹스 화면 안에서 끝나므로 정하지 않는다.","closed":"없다."},"time":{"open":"시도·성공 배지는 상시이고 최초 성공은 첫 성공 순간에 한 번이다.","closed":"최초 성공을 다투는 문구(「아직 아무도 못 했어요」 등)다."},"reward":{"open":"부스러기 배지(비소각 열쇠), 재료보다 높은 등급의 결과 배지, 실패 보상 포인트다. 결과 등급은 고른 결과 배지의 등급이다.","closed":"부스러기를 모아 재료로 바꾸는 교환이다(폐기한 「보정 카운터」와 같은 결)."},"tribe":{"rule":"캐논 10종 전체에서 레시피가 엮는 재료의 소재로 고른다. 미스터리 헌터는 아이템이 들어간 등록 조합 레시피를 소개할 때만 소문 형식으로 쓴다.","example":"포션 연금술사 — 껍데기를 모아 합성하는 화자이고 79 연금술 견습·장인과 같은 결이다."}}'::jsonb, '34는 도박의 「아깝게 놓쳤다」 연출과 닮지 않게 한다. 진행 막대, 「거의 성공」 표시, 다시 하면 된다는 문구를 쓰지 않고, 카드·배지 이름에 「아깝다」를 쓰지 않고 「부스러기」만 쓴다(샘플 이름 「아깝다 부스러기」는 내부 이름이다). 39의 사용자 의견은 레시피를 처음 성공한 유저에게만 유일한 배지 이미지를 주는 것이다. 42는 최초 발급자를 가리려면 소유 이력 조회가 필요하다(06 6.1). 켜 두면 계속 보이는 장치라 매주 기획 대상이 아니다.', 'active', NULL, 'seed'),
  -- P13 놓고 줍는 나눔이 이어진다
  ('P13', '놓고 줍는 나눔이 이어진다', '내가 놓은 것이 누군가에게 닿는 게 보이면, 아이템을 놓아 보고 남이 놓은 것도 주우며 나눔이 이어지게 된다. 지금의 교환은 받는 사람을 정하지 않고 지점에 놓고 서로 줍는 방식이다.', '내가 놓은 아이템이 주워졌다는 알림이 오고, 나도 남이 놓은 것을 주우며 나눔에 끼게 된다.', ARRAY['드랍', '홈피드', 'JAM! 배지', '알림(25)']::text[], '[{"no":22,"name":"선물 드랍","role":"main","impl":"O7(드랍에 받는 사람을 지정하는 옵션)"},{"no":24,"name":"나눔 지점","role":"main","impl":"지금 가능"},{"no":76,"name":"함께 줍기","role":"main","impl":"O5(JAM! 배지에 행동 지표를 더하는 옵션)"},{"no":77,"name":"첫 드랍","role":"main","impl":"O5"},{"no":78,"name":"나눔가","role":"main","impl":"O5"},{"no":25,"name":"내 드랍이 주워졌어요","role":"aux","impl":"지금 가능"},{"no":75,"name":"줍기 장인","role":"related","impl":"O5"}]'::jsonb, '[{"shape":"brief","note":"나눔 지점·드랍 소식, 배지 1개"},{"shape":"list","note":"배지 여러 개"}]'::jsonb, '{"condition":{"open":"첫 드랍, 서로 다른 유저 N명이 놓은 드랍 줍기(76), 내 드랍이 서로 다른 유저 N명에게 주워짐(78), 친구만 줍는 드랍(22)을 열 수 있다.","closed":"드랍·픽업 횟수 자체를 세는 조건과, 같은 아이템을 왕복해 늘릴 수 있는 조건이다."},"place":{"open":"나눔 지점(24)은 운영이 공지하고, 사람이 오가는 공원·역·관광명소 같은 지점 카테고리에서 고를 수 있다.","closed":"공통 규칙뿐이다."},"time":{"open":"상시 배지와 주 단위 나눔 지점 공지를 열 수 있다.","closed":"공통 규칙뿐이다."},"reward":{"open":"횟수형 배지이고 포인트는 작게, 기존 범위 안에서 준다. 주워짐 알림은 이미 있다.","closed":"드랍 횟수 자체에 큰 보상을 거는 것이다."},"tribe":{"rule":"캐논 10종 전체에서 나눔 소재를 TRIBES.md 표 1의 「수집·인증 문화」 같은 범주 행으로 고른다.","example":"셔터 마피아 — 흘린 파편이 뒤따르는 이들의 이정표가 된다는 원문이 나눔과 맞는다."}}'::jsonb, '76·78은 O5 계산 방식을 따른다. 두 사람이 같은 지점에서 아이템 하나를 번갈아 놓고 주우면 드랍·픽업 숫자가 왕복마다 오르므로, 76은 서로 다른 드랍한 유저 수, 78은 서로 다른 주운 유저 수로 센다. 같은 아이템 개체를 다시 주운 것은 한 번만 센다(75, P16). 자기 드랍을 자기가 다시 주울 수는 있고, 그렇게 주운 것은 배지 숫자에서 뺀다. 77은 첫 드랍 한 번이라 부풀지 않는다. 24는 06에 원문 설명이 없어 이름으로 재구성했다. 켜 두면 계속 보이는 장치라 매주 기획 대상이 아니다(25).', 'active', NULL, 'seed'),
  -- P14 함께 채우는 숫자
  ('P14', '함께 채우는 숫자', '모두의 발걸음이 숫자로 보이면, 목표를 함께 채우거나 비어 있는 곳을 채우러 가게 된다. 개인 순위 대신 참여자 합계를 보여 주고, 표본이 적은 숫자는 숨긴다.', '「이번 주 서울 체크인 120/300」처럼 모두가 쌓은 숫자가 보여서, 내 체크인이 거기에 보태진다는 걸 안다.', ARRAY['미션', '홈피드', '지점 화면(45)']::text[], '[{"no":21,"name":"도시 공동 금고","role":"main","impl":"O14(미션에 참가자 합계 공동 목표를 더하는 옵션)"},{"no":63,"name":"조용한 지점 순찰","role":"main","impl":"O12(지점별 이번 주 방문 수 표시 옵션)"},{"no":45,"name":"발자국 온도","role":"aux","impl":"O12"}]'::jsonb, '[{"shape":"square","note":"미션"},{"shape":"brief","note":"63 지점 소식"}]'::jsonb, '{"condition":{"open":"참여자 합계 목표를 걸어 달성하면 전원에게 배지를 주고(21), 이번 주 방문이 적은 지점 카테고리로 보낼 수 있다(63).","closed":"개인 기여 순위, 목표 미달 시 손해, 표본이 적은 수치 노출이다."},"place":{"open":"도시나 지역 단위 목표와 지점 카테고리를 쓸 수 있고, 전국에 유저가 있으므로 지역을 돌아가며 운영한다.","closed":"개별 유저가 드러나는 소수 표본 지점, 그리고 방문이 적은 지점을 심야·해 진 뒤·기상특보일에 권하는 것과 산·외진 지점이다."},"time":{"open":"주 단위 목표다.","closed":"공통 규칙뿐이다."},"reward":{"open":"참여자 전원 배지다.","closed":"기여도에 따라 나누는 차등 보상이다."},"tribe":{"rule":"캐논 10종 전체에서 목표 소재(지점 카테고리)에 맞는 트라이브를 TRIBES.md 표 2로 고르고, 트라이브끼리 편을 가르는 조건은 쓰지 않는다.","example":"비트 마에스트로 — 세상을 이퀄라이저로 보는 시선이라 모두의 발걸음이 막대처럼 차오르는 그림이다(편 가르기 없이)."}}'::jsonb, '21은 목표 크기를 유저 수에 맞춰 달성 가능한 크기로 잡고, 도시 하나의 목표만 보여 주며 도시끼리 견주는 표시는 닫는다(유저가 적은 초기 전제). 63 문안은 누가 다녀갔는지 말하지 않고 감시로 읽히지 않게 쓴다. 45의 사용자 의견은 표본이 적으면 숨기는 것이다. 켜 두면 계속 보이는 장치라 매주 기획 대상이 아니다.', 'paused', '필요한 기능 O12·O14 대기', 'seed'),
  -- P15 1등만 이기지 않는 판
  ('P15', '1등만 이기지 않는 판', '랭킹 기준을 주마다 돌리고, 1등이 아닌 중간 순위에도 보상하고, 평소와 반대인 조건(가장 천천히)을 열면 매주 이기는 사람이 달라진다. 늘 위에 있던 유저가 아니어도 이번 주에는 해 볼 만하다고 느낀다.', '이번 주 랭킹 기준이 지난주와 달라서, 늘 위에 있는 사람이 아니어도 이길 수 있다.', ARRAY['홈피드 랭킹 보드', '미션 랭킹', '미션']::text[], '[{"no":54,"name":"랭킹 기준 순환","role":"main","impl":"지금 가능"},{"no":55,"name":"딱 7등 보상","role":"main","impl":"O4(미션 종료 시점 순위 보상 옵션)"},{"no":56,"name":"느림보 주간","role":"main","impl":"O1(미션 조건에 시간대·페이스 등을 넘기는 옵션)"},{"no":11,"name":"오늘의 룰","role":"related","impl":"O1·O3(배수 보너스는 경제 수치 변경이라 미션·배지 보상으로 대신한다)"}]'::jsonb, '[{"shape":"list","note":"랭킹 행형"},{"shape":"square","note":"56 미션"}]'::jsonb, '{"condition":{"open":"활동 기준 다섯 가지(거리·횟수·고도·활동일·연속일)로만 랭킹 기준을 돌리고, 순위 공개 방식 3종, 참가자 수에 따라 정해지는 중간 순위 보상, 평소와 반대인 조건을 열 수 있다.","closed":"하위권 노출, 팔로워·배지 수 같은 인기·소유 기준, 참가자보다 큰 고정 순위, 트라이브끼리의 순위 비교다."},"place":{"open":"지점 조건 없이 활동 기록으로 정하는 것이 기본이다.","closed":"특정 지점에 사람을 몰리게 하는 순위 조건이다."},"time":{"open":"주 단위 랭킹이고 기준은 주마다 바꾼다.","closed":"순위가 실시간으로 뒤집혔다고 알리는 알림이다."},"reward":{"open":"정해진 순위나 중간 순위에 주는 배지와 포인트다.","closed":"1등에게만 몰아주는 큰 보상이다."},"tribe":{"rule":"캐논 10종 전체에서 기준·조건의 성격에 맞는 트라이브를 고르되, 순위를 화제로 삼는 소재는 어떤 트라이브에도 붙이지 않는다(TRIBES.md 금기 1).","example":"작심삼일 클럽 — 56 느림보 주간의 화자이고, 「나는 항상 나에게 져준다」는 남과 견주지 않는 자조다."}}'::jsonb, '55의 사용자 의견은 참가자가 정한 순위보다 적으면 받을 사람이 없으므로, 유저가 적은 초기에는 참가자 수에 따라 정해지는 순위(중간 순위 등)로 정하는 것이다. 순위 보상은 O4가 있어야 한다. 54는 랭킹 보드가 고를 수 있는 기준 중 팔로워·동기화·배지 수 기준을 이 패턴에서 닫은 것이다(06 6.1에는 열려 있는 기능).', 'active', NULL, 'seed'),
  -- P16 쌓은 만큼 이름이 붙는다
  ('P16', '쌓은 만큼 이름이 붙는다', '단계마다 이름이 붙고 다음 단계까지 남은 숫자가 보이면, 조금만 더 해 보게 된다. 이름은 JAM! 배지의 단계 이름이고, 숫자는 유저가 이미 쌓은 행동 지표다.', '「단골 명패」처럼 이름이 붙는 단계 배지가 있어서, 다음 단계까지 얼마 남았는지 알고 조금 더 해 본다.', ARRAY['JAM! 배지', '컬렉션(48)']::text[], '[{"no":20,"name":"전시관","role":"main","impl":"O5(JAM! 배지에 행동 지표를 더하는 옵션)"},{"no":41,"name":"단골 명패","role":"main","impl":"O5"},{"no":73,"name":"단골 명부","role":"main","impl":"지금 가능"},{"no":75,"name":"줍기 장인","role":"main","impl":"O5"},{"no":80,"name":"의뢰 해결사","role":"main","impl":"O5"},{"no":48,"name":"컬렉션 등급 칩","role":"aux","impl":"O9(완성 컬렉션 표지에 등급 칩을 붙이는 옵션)"},{"no":44,"name":"기념일 배지·카드","role":"related","impl":"O5(JAM! 배지에 가입 경과일 지표를 더하는 옵션)"},{"no":72,"name":"카테고리 수집가","role":"related","impl":"지금 가능"},{"no":79,"name":"연금술 견습·장인","role":"related","impl":"O5"}]'::jsonb, '[{"shape":"brief","note":"배지 1개"},{"shape":"list","note":"단계 배지 여러 개"}]'::jsonb, '{"condition":{"open":"컬렉션 완성 수(20), 같은 지점을 다른 날 3·10·30번 방문(41), 팔로워·팔로잉 수(73), 줍기 5·20·100번(75), 미션 완료 수(80)에 단계를 걸 수 있다.","closed":"부풀릴 수 있는 원시 횟수(같은 개체 재줍기, 같은 날 반복)와 팔로워를 늘리라고 몰아붙이는 단계다."},"place":{"open":"41은 단골 지점 하나(카테고리 제한 없음)이고 나머지는 장소와 무관하다.","closed":"방문 유도로 특정 지점에 사람을 몰리게 하는 단계다."},"time":{"open":"상시로 두는 장기 배지다.","closed":"기간 안에 못 채우면 사라지는 단계다."},"reward":{"open":"행동 횟수형은 포인트를 작게, 달성형(컬렉션 완성 등)은 크게 주되 기존 범위 안이다.","closed":"공통 규칙뿐이다."},"tribe":{"rule":"캐논 10종 전체에서 단계 이름의 어휘를 TRIBES.md 표 1·표 2의 소재로 고른다.","example":"장비병 환자들 — 카본·티타늄 등급처럼 단계마다 이름을 붙이는 문화다(구매 권유·가격 언급 없이)."}}'::jsonb, '75는 O5 계산 방식을 따른다. 같은 아이템을 다시 주운 것은 한 번만 센다(사용자 의견). 왕복하는 두 사람이 숫자를 부풀리는 것을 막기 위해서다. 41은 같은 날 여러 번 찾아도 한 번으로 센다. 「단골」은 41 전용으로 두고 73은 등록할 때 다른 이름을 쓴다. 73은 팔로워·팔로잉 수 기준이라 인기를 비교하거나 늘리라고 재촉하는 문구를 쓰지 않는다. 48의 사용자 의견은 완성 컬렉션 표지에 장착 아이템의 등급 칩(레어·에픽·미스틱)을 붙이는 것이다. 켜 두면 계속 보이는 장치라 매주 기획 대상이 아니다.', 'active', NULL, 'seed'),
  -- P17 쉬어도 다시 이어지는 리듬
  ('P17', '쉬어도 다시 이어지는 리듬', '쉬다 돌아와도 반겨 주고 주에 며칠만 나와도 인정해 주면, 부담 없이 다시 나오게 된다. 매일 나와야 하는 연속일 압박 대신, 쉬었다 와도 손해가 없는 기준을 쓴다.', '며칠 쉬다 돌아와도 나무라는 말 없이 배지나 소식으로 맞아 주고, 주에 며칠만 나와도 인정받는다.', ARRAY['배지', 'JAM! 배지', '알림(40)']::text[], '[{"no":29,"name":"결계 ''섬데이'' 균열","role":"main","impl":"지금 가능(배지엔진의 복귀 공백 조건)"},{"no":74,"name":"이번 주 첫 걸음","role":"main","impl":"O5(JAM! 배지에 주간 활동일 지표를 더하는 옵션)"},{"no":40,"name":"돌아온 날 알림","role":"aux","impl":"O11(인앱 알림에 복귀 계기를 더하는 옵션)"},{"no":50,"name":"내 기록 넘기","role":"related","impl":"지금 가능"},{"no":56,"name":"느림보 주간","role":"related","impl":"O1(미션 조건에 시간대·페이스 등을 넘기는 옵션)"}]'::jsonb, '[{"shape":"brief","note":"배지 1개"}]'::jsonb, '{"condition":{"open":"복귀 공백 뒤 첫 활동(29)과 한 주 3일 이상 동기화·체크인(74)을 열 수 있다.","closed":"앱을 열기만 한 날을 세는 것, 연속일을 잃으면 사라지는 진행도, 쉰 일수를 보여 주는 표시다."},"place":{"open":"정하지 않는다(장소와 무관).","closed":"복귀한 유저를 특정 지점으로 보내는 조건이다."},"time":{"open":"복귀 공백 일수와 한 주 단위를 열 수 있다.","closed":"쉰 기간을 세어 압박하는 표시다."},"reward":{"open":"복귀 배지(「침대의 중력을 이겼다」), 주간 배지, 돌아온 날 소식 알림이다.","closed":"복귀 대가로 주는 큰 포인트다."},"tribe":{"rule":"캐논 10종 전체에서 쉬었다 오는 이야기와 어울리는 트라이브를 TRIBES.md 표 1로 고르고, 자조는 남과 비교하는 말이 되지 않게 쓴다(금기 1의 예외).","example":"작심삼일 클럽 — 29 결계 「섬데이」 균열, 7일 이상 공백 뒤 복귀의 캐논 화자다."}}'::jsonb, '29의 사용자 의견은 죄책감을 주는 문구를 쓰지 않는 것이고, 「며칠이나 쉬었어요」처럼 쉰 기간을 강조하지 않는다. 74의 사용자 의견은 앱을 열기만 한 날은 세지 않는 것이다. 활동일은 활동 기록이 있는 날과 체크인한 날로 센다(06 O5 계산 방식). 40의 사용자 의견은 오래 쉬다 돌아온 유저에게 그동안의 소식을 인앱 알림함으로 주는 것이며, 푸시는 코드에서 찾지 못했다. 켜 두면 계속 보이는 장치라 매주 기획 대상이 아니다.', 'active', NULL, 'seed'),
  -- P18 지난 나와 견줘 본다
  ('P18', '지난 나와 견줘 본다', '지난주의 나와 내 이정표를 보여 주면, 남이 아니라 나를 기준으로 조금 더 해 보게 된다. 남의 기록은 기준으로 쓰지 않고 내 기록만 기준으로 삼는다.', '지난주의 나와 비교한 카드와 내 기록보다 조금 높은 목표를 받아서, 나를 이겨 보는 쪽으로 해 본다.', ARRAY['홈피드', '미션', 'JAM! 배지']::text[], '[{"no":33,"name":"내 주간 JAM","role":"main","impl":"지금 가능"},{"no":44,"name":"기념일 배지·카드","role":"main","impl":"O5(JAM! 배지에 가입 경과일 지표를 더하는 옵션)"},{"no":50,"name":"내 기록 넘기","role":"main","impl":"지금 가능"},{"no":74,"name":"이번 주 첫 걸음","role":"related","impl":"O5(JAM! 배지에 주간 활동일 지표를 더하는 옵션)"}]'::jsonb, '[{"shape":"brief","note":"회고·기념일 카드"},{"shape":"square","note":"50 미션"}]'::jsonb, '{"condition":{"open":"지난주 나의 기록(거리·횟수 등), 지난 기록보다 조금 높은 목표(50), 가입 30일·100일과 첫 배지 1년 같은 기념일(44)을 열 수 있다.","closed":"남과 견주는 문구, 지난 기록을 크게 넘는 목표, 기록이 줄었음을 나무라는 회고다."},"place":{"open":"정하지 않는다(장소와 무관).","closed":"개인 기록에서 위치·경로가 드러나는 카드다."},"time":{"open":"지난주와 이번 주를 견주는 주 단위와 가입·첫 배지 기념일을 열 수 있다.","closed":"공통 규칙뿐이다."},"reward":{"open":"회고 카드, 기념일 배지, 목표 달성 미션의 보상이다.","closed":"공통 규칙뿐이다."},"tribe":{"rule":"캐논 10종 전체에서 회고 카드는 공통 화자를 기본으로 하고, 트라이브 화자를 쓸 때는 활동의 성격에 맞춰 TRIBES.md 표 1로 고른다.","example":"아날로그 수집가 — 「낡은 물건에는 누군가의 기억이」라는 시선이라 지난 나의 기록·기념일 회고에 어울린다."}}'::jsonb, '50의 사용자 의견은 지난 기록보다 조금 높은 목표를 운영 컨텐츠 수준으로 제안하는 것이며 개인별 맞춤 미션이 아니다. 33은 기록이 줄어든 주에도 나무라거나 자극하는 문구를 쓰지 않는다. 회고 카드는 본인에게만 보이는 개인 기록이라 집계 밖으로 내보내지 않는다.', 'active', NULL, 'seed')
ON CONFLICT DO NOTHING;

-- ── ops_pattern_taste_signals ───────────────────────────────────────────
INSERT INTO public.ops_pattern_taste_signals
  (pattern_no, name, reason, basis, sort_order)
VALUES
  ('P02', '게릴라 알림(70)', '갑자기 울리는 알림으로 짧은 시간의 미션을 알리는 방향이라 놓칠까 봐 불안하게 만든다', 'estimate', 1),
  ('P03', '시간 봉인 드랍', '드랍을 봉해 두고 정한 시각까지 기다리게 하는 방향이라 카운트다운과 놓침 불안으로 흐른다', 'estimate', 1),
