-- ── ops_pattern_common_rules ────────────────────────────────────────────
INSERT INTO public.ops_pattern_common_rules
  (rule_no, title, body)
VALUES
  (1, '실존 이름 금지', '실존 상표·브랜드·대회·구단·인물 이름은 이름·문안·이미지 프롬프트 어디에도 쓰지 않는다(07 3.6).'),
  (2, '모든 패턴에서 닫는 값', '기상특보일(폭염 포함)과 심야의 외출·활동 권유, 초 단위 카운트다운, 놓칠까 봐 불안하게 만드는 문구, 순위·비교 압박, 실시간 위치·경로 공유 유도, 도시·지역끼리 견주는 표시다.'),
  (3, '시각 정의(KST)', '심야는 22:00~05:00, 새벽·이른 아침은 05:00~08:00이다. 홈피드 노출 태그 `time_dawn`은 이 새벽 정의(05~08시)와 같다.'),
  (4, '심야·새벽 카드의 노출', '심야·새벽 컨텐츠를 알리는 카드는 그 시간대에 활동한 기록이 있는 유저에게만 보인다(TRIBES.md 「시간대 화자 원칙」). 미션 목록에 올라가는 것은 권유가 아니므로 새벽 미션 자체는 공개해도 된다.'),
  (5, '코퍼스 원문 인용', '어드민 코퍼스(아이템·컬렉션 설명)의 원문은 인용할 수 있다. 다만 티켓 20260930_1517이 끝나기 전에는 윈터 검수를 통과한 문장만 쓰고, 상표·음주 권유·불법 암시가 든 문장은 인용하지 않는다.'),
  (6, '닫은 값 쓰는 법', '패턴마다 공통 규칙과 겹치는 값은 다시 풀어 쓰지 않는다. 「닫은 값은 공통 규칙뿐이다」는 그 손잡이에 더 닫을 값이 없다는 뜻이다.'),
  (7, '경제 수치', '확률·등급 비율·포인트 금액을 바꾸는 손잡이는 어느 패턴에서도 열지 않는다. 포인트가 필요한 보상은 기존 범위 안이다(07 3.6).')
ON CONFLICT DO NOTHING;

-- ── 개수 확인: 어긋나면 트랜잭션 전체를 되돌린다 ─────────────────────────────
DO $seed_check$
DECLARE
  v_found INTEGER;
BEGIN
  SELECT count(*) INTO v_found FROM public.ops_patterns WHERE pattern_no IN ('P01', 'P02', 'P03', 'P04', 'P05', 'P06', 'P07', 'P08', 'P09', 'P10', 'P11', 'P12', 'P13', 'P14', 'P15', 'P16', 'P17', 'P18');
  IF v_found <> 18 THEN
    RAISE EXCEPTION '원고의 패턴 번호 18개 중 %개만 있다', v_found;
  END IF;
  SELECT count(*) INTO v_found FROM public.ops_patterns WHERE pattern_no IN ('P01', 'P02', 'P03', 'P04', 'P05', 'P06', 'P07', 'P08', 'P09', 'P10', 'P11', 'P12', 'P13', 'P14', 'P15', 'P16', 'P17', 'P18') AND origin = 'seed';
  IF v_found <> 18 THEN
    RAISE EXCEPTION '원고의 패턴 18개 중 origin = seed인 행이 %개다', v_found;
  END IF;
  SELECT count(*) INTO v_found
    FROM (VALUES
      ('P02', '게릴라 알림(70)'),
      ('P03', '시간 봉인 드랍'),
      ('P03', '월례 걷는 날'),
      ('P03', '블랙 트랙 입구 기록(10)'),
      ('P04', '묵은 물건'),
      ('P04', '안개 걷기(36)'),
      ('P05', '재료 사냥(4)'),
      ('P06', '갈림길 투표·화요일 개표'),
      ('P06', '이번 주의 계열(67)'),
      ('P07', '지점 별명 짓기'),
      ('P08', '체크인 엽서첩'),
      ('P08', '가고 싶은 지점 핀'),
      ('P08', '새 동네 첫 체크인(81)'),
      ('P10', '세계 연표'),
      ('P10', '앙코르 미션(58)'),
      ('P10', '인접 서신 왕래(51)'),
      ('P11', '빌린 보유 확인'),
      ('P11', 'mystic 문턱 레시피'),
      ('P12', '소각의 잔재'),
      ('P12', '보정 카운터'),
      ('P12', '모은 만큼 보이는 레시피(5)'),
      ('P12', '내 믹스 노트(35)'),
      ('P13', '지점 방명록'),
      ('P13', '화요 장터'),
      ('P13', '여행하는 아이템(23)'),
      ('P13', '장물 처분의 날(66)'),
      ('P14', '세계 재고 장부'),
      ('P14', '지점 지층(52)'),
      ('P15', '종목 바꿔 보기'),
      ('P15', '트라이브 영역전(27)'),
      ('P16', '프레임·칭호 상점'),
      ('P16', '완성 보상 채우기(68)'),
      ('P16', '열독가(82)'),
      ('P17', '핑계 접수창구'),
      ('P17', '월 달력 배지'),
      ('P17', '어서 와 스탬프'),
      ('P17', '오늘의 한 걸음(37)'),
      ('P18', '지난 카드 서랍'),
      ('P18', '공유 카드 주간 테마(69)'),
      ('P18', '주간 결산(83)'),
      (NULL::text, '이달의 세 갈래'),
      (NULL::text, '택일 레인 미션'),
      (NULL::text, '의뢰서 3장(26)')
    ) AS v(pattern_no, name)
    JOIN public.ops_pattern_taste_signals t ON COALESCE(t.pattern_no, '') = COALESCE(v.pattern_no, '') AND t.name = v.name;
  IF v_found <> 43 THEN
    RAISE EXCEPTION '원고의 취향 신호 (패턴, 이름) 43쌍 중 %쌍만 있다', v_found;
  END IF;
  SELECT count(*) INTO v_found FROM public.ops_pattern_common_rules WHERE rule_no IN (1, 2, 3, 4, 5, 6, 7);
  IF v_found <> 7 THEN
    RAISE EXCEPTION '원고의 공통 규칙 번호 7개 중 %개만 있다', v_found;
  END IF;
END
$seed_check$;

COMMIT;

